<?php
declare(strict_types=1);
require_once __DIR__.'/../src/functions.php';
require_once __DIR__.'/../src/audience_store.php';
require_once __DIR__.'/../src/audience_collection_render.php';
$checks=0;
$expect=static function(bool $ok,string $label)use(&$checks):void{if(!$ok)throw new RuntimeException($label);++$checks;};
$reject=static function(callable $call)use($expect):void{try{$call();}catch(InvalidArgumentException){$expect(true,'Invalid settings rejected');return;}throw new RuntimeException('Expected rejection');};
$fields=[['id'=>12,'label'=>'Phone','field_type'=>'phone','required'=>false,'is_public'=>true,'options_json'=>'[]'],['id'=>13,'label'=>'Private','field_type'=>'text','required'=>false,'is_public'=>false,'options_json'=>'[]']];
$doc=audienceCollectionDefaults('embedded');
$expect($doc['title']==='Subscribe'&&$doc['fields']===['email'],'New embedded forms start with the email-only signup layout');
$doc['fields']=['custom:12','email','first_name'];$doc['required']=['first_name'];$doc['width']='';
$doc['labels']['custom:12']='Call me';$doc['help_text']['custom:12']='<img src=x onerror=bad()> Optional phone';$doc['tag_ids']=[7];
$doc['embedded']['show_format']=true;$doc['embedded']['show_archive']=true;$doc['embedded']['badge']=true;$doc['embedded']['badge_style']='dark';
$canonical=audienceCollectionDocument($doc,'embedded',$fields,[],[['id'=>7]]);
$expect($canonical['fields']===['custom:12','email','first_name']&&in_array('email',$canonical['required'],true),'Field order and required email survive saving');
$expect($canonical['width']===0&&$canonical['tag_ids']===[7],'Automatic width and selected audience tags survive saving');
$resource=['kind'=>'embedded','document'=>$canonical,'public_key'=>str_repeat('a',64),'archive_url'=>'https://public.example/a/community/audience_campaign_public.php?form='.str_repeat('a',64),'resize_script'=>'https://public.example/a/community/assets/js/audience-collection-resize.js'];
$html=audienceCollectionHtml($resource,$fields,[],'/native-action','signed-proof',[],'','',null,true);
$expect(str_contains($html,'class="collection-embedded"')&&str_contains($html,'--collection-width:100%'),'Embedded canvas and automatic sizing reach preview');
$expect(strpos($html,'Call me')<strpos($html,'Email address'),'Public rendering keeps authored field order');
$expect(str_contains($html,'&lt;img src=x onerror=bad()&gt;')&&!str_contains($html,'<img src=x'),'Field help is escaped');
$expect(str_contains($html,'aria-describedby="f-')&&str_contains($html,'collection-field-help'),'Field help is associated with its input');
$expect(str_contains($html,'name="email_format" value="text"')&&str_contains($html,'collection-referral-dark'),'Format choices and the selected badge style render');
$expect(str_contains($html,'View previous emails')&&str_contains($html,'signed-proof')&&str_contains($html,'name="permission"'),'Archive, signed proof and explicit permission are retained');
$expect(str_contains($html,'<button disabled>')&&!str_contains($html,'<script'),'Preview stays non-submittable and script free');
$canonical['embedded']['show_title']=false;$resource['document']=$canonical;
$expect(!str_contains(audienceCollectionHtml($resource,$fields,[],'',''),'<h1>'),'Title visibility is applied publicly');
$code=audienceCollectionEmbedCode('https://public.example/form?key=abc',$canonical);
$expect(str_contains($code,'&amp;embed=1')&&str_contains($code,'<script'),'JavaScript installation uses the public form endpoint');
$canonical['embedded']['disable_javascript']=true;$resource['document']=$canonical;
$code=audienceCollectionEmbedCode('https://public.example/form?key=abc',$canonical);
$expect(str_contains($code,'<iframe')&&!str_contains($code,'<script')&&!str_contains($code,'allow-scripts'),'JavaScript-free installation retains sandboxed native forms');
$expect(!str_contains(audienceCollectionHtml($resource,$fields,[],'',''),'<script'),'Disabled JavaScript is omitted from public rendering too');
$canonical['embedded']['remove_css']=true;$resource['document']=$canonical;
$expect(!str_contains(audienceCollectionHtml($resource,$fields,[],'',''),'box-sizing'),'Remove CSS excludes the branded stylesheet');
foreach([['embedded'=>['badge_style'=>'orange']],['embedded'=>['badge'=>'yes']],['embedded'=>'invalid'],['help_text'=>['custom:13'=>'Private help']],['tag_ids'=>[99]]]as$invalid)$reject(fn()=>audienceCollectionDocument(array_replace($doc,$invalid),'embedded',$fields,[],[['id'=>7]]));
$old=audienceCollectionDefaults('hosted');unset($old['embedded'],$old['help_text']);
$expect(audienceCollectionDocument($old,'hosted',[],[],[])['embedded']===audienceCollectionEmbedDefaults(),'Existing form documents remain compatible without migration');
echo "Embedded form: $checks checks passed.\n";
